import PAYMENT_LINKS from './payment-links.json' with { type: 'json' };

// Homepage purchase buttons link to /buy/<sku>; the Worker redirects to the Stripe Payment Link for that SKU.
// payment-links.json is generated by scripts/stripe-payment-links.sh --live.
export const BUY_PATH = /^\/buy\/([a-z0-9-]+)$/;
const BUY_HREF = /href="\/buy\/([a-z0-9-]+)"/g;
const LIVE_PAYMENT_LINK = /^https:\/\/buy\.stripe\.com\/(?!test_)[A-Za-z0-9]+$/;

export function paymentLink(sku, links = PAYMENT_LINKS) {
  const url = Object.hasOwn(links, sku) ? links[sku] : null;
  return url && LIVE_PAYMENT_LINK.test(url) ? url : null;
}

// Every /buy/<sku> on the homepage must resolve to a live-mode Payment Link, so a missing or test-mode link
// fails the build instead of a buyer's click.
export function validatePaymentLinks(html, links = PAYMENT_LINKS) {
  const skus = [...html.matchAll(BUY_HREF)].map(match => match[1]);
  if (skus.length === 0) throw new Error('homepage has no /buy/ purchase links');
  const unresolved = [...new Set(skus)].filter(sku => !paymentLink(sku, links));
  if (unresolved.length) {
    throw new Error(`no live Stripe Payment Link for ${unresolved.join(', ')}; run scripts/stripe-payment-links.sh --live`);
  }
}
